INSERT INTO `public_need` VALUES ('0b0faa0b-c96f-49fc-986f-d992ca7b8a4f','NEED-2026-005','dept-comm','u-zodwa','Community Safety Hotspot Reporting','Residents lack a trusted channel to report safety hotspots such as broken lights, open veld and drug dens.','Hotspots reported and routed to the right team within 24 hours.','COMMUNITY_SAFETY','MEDIUM',180000.00,'[\"Mobile reporting\",\"Location intelligence\",\"Analytics\"]','Gauteng','City of Tshwane','Mabopane',-25.497000,28.100000,'OPEN','2026-09-06 07:00:00.000000'),('1704cfd2-ed85-4fd9-b287-0a32b35716eb','NEED-2026-003','dept-infra','u-themba','Smart Streetlight Fault Monitoring','Streetlight faults take two weeks to repair because outages are only found through complaints.','Faults detected automatically and repaired within 3 days.','INFRASTRUCTURE','MEDIUM',240000.00,'[\"IoT\",\"Monitoring\"]','Gauteng','City of Tshwane','Soshanguve Block L',-25.540000,28.090000,'OPEN','2026-04-29 07:00:00.000000'),('1c5bf64f-59ed-445a-8743-15e7d2e9307b','NEED-2026-012','dept-infra','u-themba','Pothole reporting and repair tracking','Pothole repairs are not tracked from report to fix.','Potholes repaired within 7 days of a report.','INFRASTRUCTURE','MEDIUM',250000.00,'[\"Mobile reporting\",\"GIS\"]','Gauteng','City of Tshwane','Region 1',-25.550000,28.120000,'DRAFT','2026-09-25 13:00:00.000000'),('20ef81af-d066-431e-967d-e13bd4dbd889','NEED-2026-009','dept-ict','u-musa','Laptops for ward councillor support office','Ward support staff share two ageing laptops, delaying constituency case logging.','Each support officer has a working laptop.','ICT_OPERATIONS','MEDIUM',48500.00,'[]','Gauteng','City of Tshwane','Civic Centre',-25.747000,28.188000,'OPEN','2026-09-23 07:00:00.000000'),('2f1273b5-ec15-4d00-8858-7631ff82fccd','NEED-2026-006','dept-econ','u-refilwe','Informal Trader Digital Payments Pilot','Informal traders at taxi ranks lose sales because customers increasingly pay digitally.','200 traders accepting digital payments, with simple bookkeeping.','LOCAL_ECONOMIC_DEVELOPMENT','MEDIUM',95000.00,'[\"Mobile payments\",\"Onboarding\",\"Analytics\"]','Gauteng','City of Tshwane','Mabopane Station',-25.500000,28.095000,'OPEN','2026-09-16 07:00:00.000000'),('52ab0582-c774-4117-b847-7fbb1625bc48','NEED-2026-010','dept-env','u-thandi','Drone survey of landfill sites','Landfill airspace estimates are two years old.','Accurate remaining-airspace model for 3 landfills.','WASTE_ENVIRONMENT','MEDIUM',145000.00,'[\"Drone survey\",\"GIS\",\"Analytics\"]','Gauteng','City of Tshwane','Soshanguve landfill',-25.515000,28.080000,'OPEN','2026-09-24 07:00:00.000000'),('86b22cd2-40ee-44b8-9384-7107ccd423db','NEED-2026-011','dept-econ','u-refilwe','Branded marketing gazebos','Events team wants new branded gazebos.','Branded presence at events.','LOCAL_ECONOMIC_DEVELOPMENT','LOW',62000.00,'[]','Gauteng','City of Tshwane','Civic Centre',-25.747000,28.188000,'OPEN','2026-09-19 07:00:00.000000'),('a91568e3-c4a8-41fe-9cde-4ac9ad242f35','NEED-2026-001','dept-infra','u-themba','Water Leak Detection - Mamelodi','Non-revenue water losses in Mamelodi exceed 40% and leaks are only found when residents report them.','Detect leaks early, cut water losses by a quarter and repair leaks within 24 hours.','WATER_ENERGY','HIGH',720000.00,'[\"IoT\",\"Monitoring\",\"Analytics\",\"Mobile reporting\"]','Gauteng','City of Tshwane','Mamelodi (Wards 15-18)',-25.712000,28.370000,'OPEN','2026-03-10 07:00:00.000000'),('ae3d20cf-22fc-4f0f-8809-355ca66d104c','NEED-2026-002','dept-econ','u-refilwe','Digital Business Permit Service','Informal and small businesses wait on average 21 days for a trading permit because applications are paper-based.','Permits issued within 5 working days, applied for online or on a phone.','DIGITAL_SERVICES','HIGH',320000.00,'[\"Digital public services\",\"Workflow\",\"Mobile reporting\"]','Gauteng','City of Tshwane','Region 3',-25.747900,28.229300,'OPEN','2026-05-29 07:00:00.000000'),('b6dde8b8-2ed9-4484-87cc-50053cf44725','NEED-2026-007','dept-env','u-thandi','Protective gloves & clean-up kits','Volunteer clean-up teams in Ward 24 lack protective equipment.','Safe volunteer clean-ups.','WASTE_ENVIRONMENT','LOW',3200.00,'[]','Gauteng','City of Tshwane','Ward 24',-25.530000,28.105000,'OPEN','2026-09-24 08:00:00.000000'),('ec06b04a-9d13-4b6b-8135-4b4a04aa94e5','NEED-2026-004','dept-env','u-thandi','Illegal Dumping Monitoring Solution','Illegal dumping is increasing across several wards. The municipality needs a technology-enabled method for identifying, mapping and monitoring illegal dumping hotspots.','Fewer illegal dumping hotspots across 12 wards, with a live hotspot map for enforcement teams.','WASTE_ENVIRONMENT','HIGH',500000.00,'[\"GIS\",\"Mobile reporting\",\"Analytics\",\"Location intelligence\",\"Monitoring\",\"Computer vision (optional)\"]','Gauteng','City of Tshwane','Soshanguve (Wards 20-31)',-25.520000,28.100000,'OPEN','2026-09-02 07:00:00.000000'),('ec6d0631-fdbe-417f-a42c-65aa39e41259','NEED-2026-008','dept-comm','u-zodwa','Community hall sound system','The Mabopane community hall has no working PA system for public meetings.','Public meetings are audible to 300 people.','COMMUNITY_FACILITIES','LOW',18000.00,'[]','Gauteng','City of Tshwane','Mabopane Community Hall',-25.499000,28.102000,'OPEN','2026-09-20 07:00:00.000000');
